\begin{example}[a non-differentiable curve]
  \label{ex:dc-ch0-3-2}
  \dcref{ch0:3.2}


  The curve $\alpha:\mathbb{R}\to\mathbb{R}^2$, $\alpha(t)=(t,|t|)$, is not
  differentiable at $t=0$ (Fig. 5).
\end{example}

